-- ==================================================================
-- DATABASE INITIALIZATION AND POPULATION SCRIPT (15 MONTHS HISTORY)
-- ==================================================================

-- Drop existing tables to ensure a clean state (respecting dependencies)
DROP TABLE IF EXISTS transaction;
DROP TABLE IF EXISTS savings_goal;
DROP TABLE IF EXISTS category CASCADE;
DROP TABLE IF EXISTS app_user CASCADE;

-- Create tables matching JPA Entities
CREATE TABLE app_user (
    id UUID PRIMARY KEY,
    username VARCHAR(255) NOT NULL UNIQUE,
    password VARCHAR(255) NOT NULL
);

CREATE TABLE category (
    id UUID PRIMARY KEY,
    name VARCHAR(100) NOT NULL UNIQUE
);

CREATE TABLE savings_goal (
    id UUID PRIMARY KEY,
    name VARCHAR(255) NOT NULL,
    description VARCHAR(255),
    amount DOUBLE PRECISION NOT NULL,
    current_amount DOUBLE PRECISION DEFAULT 0.0,
    deadline DATE NOT NULL,
    user_id UUID NOT NULL REFERENCES app_user(id) ON DELETE CASCADE
);

CREATE TABLE transaction (
    id UUID PRIMARY KEY,
    name VARCHAR(255) NOT NULL,
    description VARCHAR(255),
    amount DOUBLE PRECISION NOT NULL,
    transaction_date TIMESTAMP NOT NULL,
    transaction_type VARCHAR(255) NOT NULL,
    category_id UUID NOT NULL REFERENCES category(id) ON DELETE RESTRICT,
    user_id UUID NOT NULL REFERENCES app_user(id) ON DELETE CASCADE
);

